import React, { forwardRef, ReactElement } from 'react';
import { isElement } from 'react-is';
import styled from 'styled-components';

import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { Action } from './Action.js';
import { Navigation } from './Navigation.js';
import { Prefix } from './Prefix.js';
import { Subtitle } from './Subtitle.js';
import { Suffix } from './Suffix.js';
import { Title } from './Title.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { _isStringChildren } from '../../core/utils/is-string-children.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { Divider } from '../../typography/Divider.js';

//#region Typings
/** Accepted properties for TitleBar */
export interface TitleBarProps extends WithChildren, StylingProps, DataTestId {
  /**
   * Whether a divider is displayed after the TitleBar component.
   * @defaultValue true
   */
  showDivider?: boolean;
}

type TitleBarSlots = {
  title?: ReactElement;
  subtitle?: ReactElement;
  navigation?: ReactElement;
  prefix?: ReactElement;
  suffix?: ReactElement;
  action?: ReactElement;
};
//#endregion

//#region Styled Components
const StyledDivider = /* @__PURE__ */ styled(Divider)({
  marginTop: Spacings.Size8,
});

const StyledTitleSubtitleWrapper = styled('div')<{
  $childrenAreText: boolean;
}>(
  {
    flexGrow: 1,
    overflow: 'hidden',
    display: 'flex',
    flexDirection: 'column',
    gap: Spacings.Size4,
  },
  ({ $childrenAreText }) =>
    $childrenAreText && {
      width: 'clamp(400px, 400px, 100%)',
    },
);
//#endregion

/** Iterates over child nodes to extract specific component slots. */
function getTitleBarSlots(children: React.ReactNode) {
  const slots: TitleBarSlots = {};

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case Title:
          slots.title = child;
          break;
        case Subtitle:
          slots.subtitle = child;
          break;
        case Navigation:
          slots.navigation = child;
          break;
        case Suffix:
          slots.suffix = child;
          break;
        case Prefix:
          slots.prefix = child;
          break;
        case Action:
          slots.action = child;
          break;
      }
    }
  });

  return slots;
}

/**
 * The TitleBar component can be used for a consistent layout for section titles and provides
 * layout slots for interactive and navigational elements.
 */
export const _TitleBar = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  TitleBarProps
>((props: TitleBarProps, forwardedRef) => {
  const {
    children,
    showDivider = true,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    ...remainingProps
  }: TitleBarProps = props;
  const slots = getTitleBarSlots(children);

  const titleIsText =
    !!slots.title && _isStringChildren(slots.title.props.children);
  const subtitleIsText =
    !!slots.subtitle && _isStringChildren(slots.subtitle?.props.children);
  const titleAndSubtitleIsText =
    (titleIsText && !slots.subtitle) || (titleIsText && subtitleIsText);

  return (
    <Flex
      ref={forwardedRef}
      {...remainingProps}
      width="100%"
      flexDirection="column"
      gap={0}
      className={consumerClassName}
      style={consumerStyle}
      data-testid={dataTestId}
    >
      <Flex flexDirection="column" gap={8}>
        {slots.navigation && (
          <Flex width="100%" justifyContent="space-between" gap={8}>
            {slots.navigation}
            {slots.action}
          </Flex>
        )}
        <Flex width="100%" justifyContent="space-between" gap={8}>
          <Flex flexWrap="wrap" gap={8} width="100%" minWidth={0}>
            {slots.prefix}
            {(slots.title || slots.subtitle) && (
              <StyledTitleSubtitleWrapper
                $childrenAreText={titleAndSubtitleIsText}
              >
                {slots.title}
                {slots.subtitle}
              </StyledTitleSubtitleWrapper>
            )}
            {slots.suffix}
          </Flex>
          {!slots.navigation && slots.action}
        </Flex>
      </Flex>
      {showDivider && <StyledDivider flexItem />}
    </Flex>
  );
});

_TitleBar['displayName'] = 'TitleBar';

/**
 * The TitleBar component can be used for a consistent layout for section titles and provides
 * layout slots for interactive and navigational elements.
 */
export const TitleBar = Object.assign(_TitleBar, {
  Title,
  Subtitle,
  Suffix,
  Navigation,
  Prefix,
  Action,
});
